        else None

        else None
    )
    if (
        from_time is not None
        and to_time is not None
        and from_time > to_time
    ):
        raise ValidationError("查询参数 from 不得晚于 to")

    events, next_after = store.list_did_deactivation_events(
        tenant,
        after,
        limit,
        did=did,
        key_version=key_version,
        from_time=from_time,
